CREATE TRIGGER cl07.trg_C_ins ON cl07.C AFTER INSERT AS
BEGIN
    SET NOCOUNT ON;
    UPDATE cl07.D
    SET cnt = cnt + (SELECT COUNT(*) FROM inserted)
    WHERE id = 1;
END;

