CREATE TRIGGER cl08.trg_Acct_upd ON cl08.Acct AFTER UPDATE AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted WHERE touched < 3) RETURN;
    UPDATE a
    SET touched = a.touched + 1
    FROM cl08.Acct AS a
    INNER JOIN inserted AS i ON a.id = i.id
    WHERE i.touched < 3;
END;

