CREATE TRIGGER cl10.trg_Region_del_dyn ON cl10.Region AFTER DELETE AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @n int = (SELECT COUNT(*) FROM deleted);
    EXEC sys.sp_executesql
        N'UPDATE cl10.Counter SET n = n + @n WHERE name = ''region_deleted'';',
        N'@n int',
        @n = @n;
END;

